// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/guests", wrapper.ListGuests)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/guests", wrapper.ToggleGuests)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/guests", wrapper.CreateGuest)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/guests/{guestId}", wrapper.DeleteGuest)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/guests/{guestId}", wrapper.UpdateGuest)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/guest-links/{linkKey}", wrapper.DeleteGuestLink)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/guest-links/{linkKey}", wrapper.UpsertGuestLink)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/clusters", wrapper.GetClusterOverview)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/guest-imports", wrapper.ImportGuests)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/scenarios", wrapper.ListScenarios)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/scenarios", wrapper.ReplaceScenarios)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/scenarios/calculate", wrapper.CalculateProposals)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/scenarios/{capacity}/assignments/{guestId}", wrapper.DeleteAssignment)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/scenarios/{capacity}/assignments/{guestId}", wrapper.SetAssignment)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/scenarios/{capacity}/tables", wrapper.ResetPlan)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/scenarios/{capacity}/tables", wrapper.AddTable)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/scenarios/{capacity}/tables/{tableNumber}", wrapper.DeleteTable)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/health", wrapper.GetHealth)
	})

	return r
}

